#!/usr/bin/env bash
set -euo pipefail

# Assembles charts/ai-services/.local/secrets.yaml from the key material
# in the repo-root .local/ (generated by hacks/setup_keys.sh) plus
# externally-sourced config (Postgres), which can be overridden via
# environment variables.

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT_LOCAL="$(cd "$SCRIPT_DIR/../.." && pwd)/.local"
OUT="$SCRIPT_DIR/.local/secrets.yaml"

PG_HOST="postgres-postgresql.postgres.svc.cluster.local"

for f in client-private.pem client-secret litellm-master-key litellm-salt-key \
         langfuse-public-key langfuse-secret-key; do
    if [[ ! -f "$ROOT_LOCAL/$f" ]]; then
        echo "❌ Missing $ROOT_LOCAL/$f — run hacks/setup_keys.sh and hacks/langfuse.sh first" >&2
        exit 1
    fi
done

mkdir -p "$(dirname "$OUT")"

# The collector authenticates to Langfuse with Basic base64(publicKey:secretKey)
# of the project hacks/langfuse.sh creates.
LANGFUSE_OTLP_BASIC=$(printf '%s:%s' \
    "$(tr -d '\n' < "$ROOT_LOCAL/langfuse-public-key")" \
    "$(tr -d '\n' < "$ROOT_LOCAL/langfuse-secret-key")" | base64 | tr -d '\n')

# memory-service (Python, SQLAlchemy async) needs the asyncpg driver;
# LiteLLM takes a plain postgresql:// URL. The Temporal UI client secret must
# match the realm's ${vault.ai-services-temporal-ui-client-secret}, which
# charts/keycloak renders from the same .local/client-secret.
jq -n \
    --rawfile privateKey       "$ROOT_LOCAL/client-private.pem" \
    --rawfile clientSecret     "$ROOT_LOCAL/client-secret" \
    --rawfile litellmMasterKey "$ROOT_LOCAL/litellm-master-key" \
    --rawfile litellmSaltKey   "$ROOT_LOCAL/litellm-salt-key" \
    --arg pgConnLitellm   "${LITELLM_PG_CONN:-postgresql://litellm_user:postgres@${PG_HOST}:5432/litellm}" \
    --arg pgConnMemory    "${MEMORY_PG_CONN:-postgresql+asyncpg://memory_user:postgres@${PG_HOST}:5432/memory}" \
    --arg temporalPgHost  "${TEMPORAL_PG_HOST:-${PG_HOST}}" \
    --arg temporalPgPort  "${TEMPORAL_PG_PORT:-5432}" \
    --arg temporalPgUser  "${TEMPORAL_PG_USER:-temporal_user}" \
    --arg temporalPgPass  "${TEMPORAL_PG_PASSWORD:-postgres}" \
    --arg langfuseOtlpBasic "$LANGFUSE_OTLP_BASIC" \
    '{
        "ai-services": {
            secrets: {
                accessControlKeys: {
                    privateKey: $privateKey
                },
                otelCollectorKeys: {
                    langfuseOtlpBasic: $langfuseOtlpBasic
                },
                litellmProxyKeys: {
                    postgresConnectionString: $pgConnLitellm,
                    masterKey: ($litellmMasterKey | rtrimstr("\n")),
                    saltKey:   ($litellmSaltKey   | rtrimstr("\n"))
                },
                memoryServiceKeys: {
                    postgresConnectionString: $pgConnMemory
                },
                temporalKeys: {
                    postgresHost:     $temporalPgHost,
                    postgresPort:     $temporalPgPort,
                    postgresUser:     $temporalPgUser,
                    postgresPassword: $temporalPgPass
                },
                temporalUiKeys: {
                    authClientSecret: ($clientSecret | rtrimstr("\n"))
                }
            }
        }
    }' | yq -P > "$OUT"

echo "✅ Wrote AI Services secrets into $OUT"
